const h = React.createElement;
const clamp = {extrapolateLeft:'clamp',extrapolateRight:'clamp'};
const dur = durationInFrames;
const cx = width * 0.5;
const cy = height * 0.48;

const tools = [
  {label:'Browser', angle: 0},
  {label:'Code', angle: 45},
  {label:'Spreadsheet', angle: 90},
  {label:'Email', angle: 135},
  {label:'Document', angle: 180},
  {label:'Terminal', angle: 225},
  {label:'Calendar', angle: 270},
  {label:'Search', angle: 315}
];

const tentacleLen = Math.min(width, height) * 0.28;
const bodyR = 52;

const allCheckDelay = 6;
const perItemDelay = 3;

const moveOnStart = Math.min(dur * 0.55, 50);
const bodyDriftX = interpolate(frame, [moveOnStart, Math.max(moveOnStart+1, dur)], [0, width * 0.08], clamp);
const bodyDriftY = interpolate(frame, [moveOnStart, Math.max(moveOnStart+1, dur)], [0, -height * 0.03], clamp);

const tentacles = tools.map((t, i) => {
  const rad = (t.angle * Math.PI) / 180;
  const ex = Math.cos(rad) * tentacleLen;
  const ey = Math.sin(rad) * tentacleLen;
  const tipX = cx + ex + bodyDriftX;
  const tipY = cy + ey + bodyDriftY;
  const midX = cx + ex * 0.5 + Math.sin(frame * 0.08 + i) * 6 + bodyDriftX;
  const midY = cy + ey * 0.5 + Math.cos(frame * 0.1 + i) * 6 + bodyDriftY;
  const startX = cx + bodyDriftX;
  const startY = cy + bodyDriftY;

  const isDoc = t.label === 'Document';
  const checkIn = allCheckDelay + i * perItemDelay;
  const checkProg = spring({frame: frame - checkIn, fps, config:{damping:12, stiffness:200}});

  const iconColor = isDoc ? D.red : D.green;
  const iconText = isDoc ? '\u26A0\uFE0F' : '\u2713';
  const iconBg = isDoc ? 'rgba(255,60,60,0.15)' : 'rgba(60,255,120,0.12)';

  const wiggle = isDoc ? Math.sin(frame * 0.3) * 3 : 0;

  const pathD = 'M ' + startX + ' ' + startY + ' Q ' + midX + ' ' + midY + ' ' + tipX + ' ' + tipY;

  return h(React.Fragment, {key: i},
    h('svg', {style:{position:'absolute',left:0,top:0,width:width,height:height,pointerEvents:'none'}},
      h('path', {d: pathD, stroke: isDoc ? D.red : D.violet, strokeWidth: 4, fill:'none', opacity: 0.6,
        strokeDasharray: isDoc ? '8 4' : 'none'})
    ),
    h('div', {style:{
      position:'absolute',
      left: tipX - 38,
      top: tipY - 38 + wiggle,
      width: 76, height: 76,
      borderRadius: 14,
      background: D.surface,
      border: '2px solid ' + (isDoc ? D.red : D.violet),
      display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center',
      opacity: interpolate(frame, [0, 8], [0, 1], clamp),
      boxShadow: isDoc ? '0 0 18px ' + D.red : 'none'
    }},
      h('span', {style:{fontSize:13, color: D.text_dim, fontFamily: D.font_mono, marginBottom:2}}, t.label),
      h('span', {style:{
        fontSize: 22,
        color: iconColor,
        opacity: checkProg,
        transform: 'scale(' + checkProg + ')',
        fontWeight:'bold'
      }}, iconText)
    )
  );
});

const bodyScale = spring({frame: frame, fps, config:{damping:16, stiffness:140}});

const eyeOffX = interpolate(frame, [moveOnStart, Math.max(moveOnStart+1, dur)], [0, 6], clamp);

const body = h('div', {style:{
  position:'absolute',
  left: cx - bodyR + bodyDriftX,
  top: cy - bodyR + bodyDriftY,
  width: bodyR * 2, height: bodyR * 2,
  borderRadius: '50%',
  background: 'radial-gradient(circle at 40% 35%, ' + D.violet + ', ' + D.surface + ')',
  border: '3px solid ' + D.violet,
  transform: 'scale(' + bodyScale + ')',
  display:'flex', alignItems:'center', justifyContent:'center',
  boxShadow: '0 0 30px ' + D.violet
}},
  h('div', {style:{display:'flex', gap:16}},
    h('div', {style:{width:16,height:16,borderRadius:'50%',background:D.bg,position:'relative',overflow:'hidden'}},
      h('div', {style:{width:8,height:8,borderRadius:'50%',background:D.white,position:'absolute',top:4,left:4+eyeOffX}})
    ),
    h('div', {style:{width:16,height:16,borderRadius:'50%',background:D.bg,position:'relative',overflow:'hidden'}},
      h('div', {style:{width:8,height:8,borderRadius:'50%',background:D.white,position:'absolute',top:4,left:4+eyeOffX}})
    )
  )
);

const textStart = Math.min(dur * 0.5, 45);
const textProg = spring({frame: frame - textStart, fps, config:{damping:14, stiffness:180}});
const quoteOp = interpolate(frame, [textStart, Math.min(textStart + 10, dur - 1)], [0, 1], clamp);

const quote = h('div', {style:{
  position:'absolute',
  bottom: height * 0.08,
  left: 0, right: 0,
  textAlign:'center',
  opacity: quoteOp,
  transform: 'translateY(' + ((1 - textProg) * 30) + 'px)'
}},
  h('span', {style:{
    fontFamily: D.font_display,
    fontSize: 42,
    fontWeight: 900,
    color: D.violet,
    letterSpacing: 3,
    textShadow: '0 0 24px ' + D.violet + ', 0 0 48px ' + D.violet
  }}, '"YOU NEVER NEED TO LEAVE."')
);

const bg = h('div', {style:{
  position:'absolute', inset:0,
  background: D.bg
}});

return h(React.Fragment, null, bg, ...tentacles, body, quote);
